package com.rpb.reservation.workforce.documents;
import static com.rpb.reservation.workforce.documents.DocumentDtos.*;
import com.rpb.reservation.workforce.application.*;import com.rpb.reservation.workforce.persistence.WorkforceEmployeeRepository;
import com.rpb.reservation.workforce.domain.WorkforceException;import com.rpb.reservation.walkin.api.CurrentActor;
import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true)
public class EmployeeDocumentService {
 private final WorkforceAccess access;private final WorkforceEmployeeRepository employees;private final DocumentRepository repository;private final WorkforceAudit audit;
 public EmployeeDocumentService(WorkforceAccess access,WorkforceEmployeeRepository employees,DocumentRepository repository,WorkforceAudit audit){this.access=access;this.employees=employees;this.repository=repository;this.audit=audit;}
 private void authorize(CurrentActor actor,UUID store,UUID employee){access.enter(actor,store);var e=employees.find(actor.tenantId(),employee).orElseThrow(WorkforceException::missing);if(!e.storeIds().contains(store))throw WorkforceException.missing();if(!actor.actorId().equals(e.accountId())){access.manage(actor,store);if(!access.managedStores(actor).containsAll(e.storeIds()))throw WorkforceException.forbidden();}}
 private void lock(CurrentActor actor,UUID store,UUID employee){access.sourceWrite(actor);employees.lock(employee);authorize(actor,store,employee);}
 public List<Type> types(CurrentActor actor,UUID store){access.enter(actor,store);return repository.types(actor.tenantId());}
 @Transactional public Type type(CurrentActor actor,UUID store,UUID id,TypeWrite c){access.enter(actor,store);access.headOffice(actor);if(c==null||c.expectedVersion()==null||c.expectedVersion()<0||c.enabled()==null)throw WorkforceException.invalid();String name=text(c.name(),80,true);repository.lockTypes(actor.tenantId());var old=repository.type(actor.tenantId(),id).orElse(null);boolean deleted=Boolean.TRUE.equals(c.deleted());if(old!=null&&c.expectedVersion()==0&&old.name().equals(name)&&old.enabled()==c.enabled()&&!deleted)return old;if((old==null?0:old.version())!=c.expectedVersion())throw WorkforceException.conflict();if(deleted&&(old==null||repository.referenced(actor.tenantId(),id)))throw new WorkforceException("WORKFORCE_DOCUMENT_TYPE_IN_USE",409);repository.saveType(actor.tenantId(),id,name,c.enabled(),c.expectedVersion()+1,deleted);var result=new Type(id,name,c.enabled(),c.expectedVersion()+1);if(!deleted&&repository.type(actor.tenantId(),id).isEmpty())throw WorkforceException.missing();audit.changed(actor,store,"document-type.save",id,old,result);return result;}
 public Page list(CurrentActor actor,UUID store,UUID employee){authorize(actor,store,employee);return new Page(repository.types(actor.tenantId()),repository.list(actor.tenantId(),employee));}
 private Document document(CurrentActor actor,UUID employee,UUID id){return repository.find(actor.tenantId(),employee,id,false).orElseThrow(WorkforceException::missing);}
 @Transactional public Document save(CurrentActor actor,UUID store,UUID employee,UUID id,Write c){lock(actor,store,employee);if(c==null||c.expectedVersion()==null||c.expectedVersion()<0||c.typeId()==null)throw WorkforceException.invalid();repository.lockTypes(actor.tenantId());var old=repository.find(actor.tenantId(),employee,id,true).orElse(null);boolean deleted=Boolean.TRUE.equals(c.deleted());String number=text(c.number(),100,false),notes=text(c.notes(),2000,false);
  boolean metadata=c.holderName()!=null||c.approvedOn()!=null||c.prEffectiveOn()!=null;
  String holderName=metadata?text(c.holderName(),100,false):old==null?"":old.holderName();
  var approvedOn=metadata?c.approvedOn():old==null?null:old.approvedOn();var prEffectiveOn=metadata?c.prEffectiveOn():old==null?null:old.prEffectiveOn();
  if(c.expiresOn()!=null&&(approvedOn!=null&&approvedOn.isAfter(c.expiresOn())||prEffectiveOn!=null&&prEffectiveOn.isAfter(c.expiresOn())))throw WorkforceException.invalid();
  for(var date:java.util.Arrays.asList(approvedOn,prEffectiveOn,c.expiresOn()))if(date!=null&&(date.getYear()<1900||date.getYear()>2200))throw WorkforceException.invalid();
 if(old!=null&&repository.deleted(actor.tenantId(),employee,id))throw WorkforceException.missing();var type=repository.type(actor.tenantId(),c.typeId()).orElseThrow(WorkforceException::missing);if(!type.enabled()&&(old==null||!old.typeId().equals(type.id())))throw WorkforceException.invalid();if(old!=null&&c.expectedVersion()==0&&old.typeId().equals(c.typeId())&&old.number().equals(number)&&Objects.equals(old.expiresOn(),c.expiresOn())&&old.notes().equals(notes)&&old.holderName().equals(holderName)&&Objects.equals(old.approvedOn(),approvedOn)&&Objects.equals(old.prEffectiveOn(),prEffectiveOn)&&!deleted)return old;if((old==null?0:old.version())!=c.expectedVersion())throw WorkforceException.conflict();if(old==null&&(deleted||repository.list(actor.tenantId(),employee).size()>=100))throw WorkforceException.invalid();repository.save(actor.tenantId(),employee,id,type.id(),number,c.expiresOn(),notes,c.expectedVersion()+1,actor.actorId(),deleted,holderName,approvedOn,prEffectiveOn);var saved=repository.find(actor.tenantId(),employee,id,true).orElseThrow(WorkforceException::missing);audit.changed(actor,store,deleted?"document.delete":"document.save",id,summary(old),summary(saved));return saved;}
 @Transactional public Document upload(CurrentActor actor,UUID store,UUID employee,UUID doc,UUID fileId,long version,String filename,byte[] bytes){lock(actor,store,employee);var current=document(actor,employee,doc);var file=DocumentFileRules.validate(fileId,filename,bytes);var old=repository.file(actor.tenantId(),employee,doc,fileId);if(old.isPresent()){if(old.get().deleted()||!old.get().hash().equals(file.hash()))throw WorkforceException.conflict();return current;}if(current.version()!=version)throw WorkforceException.conflict();if(current.attachments().size()>=5)throw new WorkforceException("WORKFORCE_DOCUMENT_ATTACHMENT_LIMIT",400);repository.file(actor.tenantId(),employee,doc,actor.actorId(),file);repository.bump(actor.tenantId(),employee,doc,actor.actorId());audit.changed(actor,store,"document.attachment.upload",fileId,null,Map.of("documentId",doc,"size",bytes.length));return document(actor,employee,doc);}
 public FileData download(CurrentActor actor,UUID store,UUID employee,UUID doc,UUID id){authorize(actor,store,employee);document(actor,employee,doc);return repository.file(actor.tenantId(),employee,doc,id).filter(f->!f.deleted()).orElseThrow(WorkforceException::missing);}
 @Transactional public Document deleteFile(CurrentActor actor,UUID store,UUID employee,UUID doc,UUID id,Version c){lock(actor,store,employee);var current=document(actor,employee,doc);var file=repository.file(actor.tenantId(),employee,doc,id).orElseThrow(WorkforceException::missing);if(file.deleted())return current;if(c==null||c.expectedVersion()==null||current.version()!=c.expectedVersion())throw WorkforceException.conflict();repository.deleteFile(actor.tenantId(),employee,doc,id);repository.bump(actor.tenantId(),employee,doc,actor.actorId());audit.changed(actor,store,"document.attachment.delete",id,Map.of("documentId",doc),null);return document(actor,employee,doc);}
 private Map<String,Object> summary(Document d){return d==null?null:Map.of("id",d.id(),"typeId",d.typeId(),"version",d.version());}
 private String text(String v,int max,boolean required){String s=v==null?"":v.trim();if(s.length()>max||required&&s.isBlank())throw WorkforceException.invalid();return s;}
}
